use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode a string for use as a URL query value (RFC 3986 unreserved
/// characters pass through; everything else, byte by byte, is %XX-encoded).
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        let unreserved = b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~');
        if unreserved {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0F) as usize] as char);
        }
    }
    out
}

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn importance_rank(i: Importance) -> u8 {
    match i {
        Importance::MustRead => 0,
        Importance::WorthALook => 1,
        Importance::Skip => 2,
    }
}

fn render_entry(out: &mut String, e: &ItemVerdict) {
    out.push_str("- [");
    out.push_str(importance_label(e.importance));
    out.push_str(" / ");
    out.push_str(category_label(e.category));
    out.push_str("] ");
    out.push_str(e.title.trim());
    if !e.feed.trim().is_empty() {
        out.push_str(" (");
        out.push_str(e.feed.trim());
        out.push(')');
    }
    out.push('\n');
    if !e.link.trim().is_empty() {
        out.push_str("  ");
        out.push_str(e.link.trim());
        out.push('\n');
    }
    let summary = e.summary.trim();
    if !summary.is_empty() {
        out.push_str("  ");
        out.push_str(summary);
        out.push('\n');
    }
}

fn render_message(d: &Digest) -> String {
    let mut msg = String::new();
    msg.push_str("Digest for ");
    msg.push_str(d.date.trim());
    msg.push_str("\n\n");

    let overview = d.overview.trim();
    if !overview.is_empty() {
        msg.push_str(overview);
        msg.push_str("\n\n");
    }

    let mut entries: Vec<&ItemVerdict> = d.entries.iter().filter(|e| e.kept).collect();
    entries.sort_by_key(|e| importance_rank(e.importance));

    if entries.is_empty() {
        msg.push_str("No items made the digest today.\n");
    } else {
        for e in entries {
            render_entry(&mut msg, e);
        }
    }

    msg.push('\n');
    msg.push_str(&format!("{} item(s) considered.", d.considered.len()));
    msg
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment lookup (approved grant extension). The result is fetched
        // but deliberately not used, so the node's output is unchanged; a
        // transport failure is returned as a value and simply ignored.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&composed.overview));
        let _enrichment: Result<String, String> = http_client::fetch(&url);

        let message = render_message(&composed);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

Notes:
- `ensures present(published)` holds because `published` is always set. It is a `bool` taken from `notify`.
- **Deployment risk:** the graph still declares only `Notifier<'digest'>`. A host that binds imports from the current graph definition may refuse to instantiate this component until the graph update ships, because it imports `http-client`. If that happens, either deploy alongside the graph change or temporarily remove the import and the `fetch` call.
- **URL and query value:** "The input's text" is interpreted as the digest's `overview`, percent-encoded into the `q` parameter.
- **Why `fetch` and not `get`:** I used `fetch` so that a transport failure is just a value, which I discard. That keeps the output unchanged. A host outside the allowlist would still trap.

